508: /// `p` as the child resolves it: against the child's working directory (the repository root)
509: /// when relative, `.` and `..` folded lexically (as `path.join` does).
510: fn in_child_cwd(repo_root: &Path, p: &str) -> PathBuf {
511:     let p = Path::new(p);
512:     let full = if p.is_absolute() {
513:         p.to_path_buf()
514:     } else {
515:         repo_root.join(p)
516:     };
517:     let mut out = PathBuf::new();
518:     for c in full.components() {
519:         match c {
520:             std::path::Component::CurDir => {}
521:             std::path::Component::ParentDir => {
522:                 out.pop();
523:             }
524:             other => out.push(other.as_os_str()),
525:         }
526:     }
527:     out
528: }
529: 
530: /// Whether `p` lies inside `root` (or is it): lexically, as `Get-RepoRelativePath` decides (a
531: /// relative `p` against the current directory), or (wave 4f, F25-2) once the links on the way are
532: /// resolved - the deepest existing ancestor of `p` and the root canonicalised - so a junction or a
533: /// symbolic link into the repository is caught too.
534: pub fn path_inside(root: &Path, p: &Path) -> bool {
535:     let full = if p.is_absolute() {
536:         p.to_path_buf()
537:     } else {
538:         std::env::current_dir().unwrap_or_default().join(p)
539:     };
540:     if c3_core::paths::repo_relative(root, &full).is_some() {
541:         return true;
542:     }
543:     match (resolve_existing(root), resolve_existing(&full)) {
544:         (Some(r), Some(f)) => c3_core::paths::repo_relative(&r, &f).is_some(),
545:         _ => false,
546:     }
547: }
548: 
549: /// `p` with its deepest existing ancestor canonicalised (links resolved, the verbatim prefix
550: /// dropped) and the rest appended; `None` when no ancestor exists.
551: fn resolve_existing(p: &Path) -> Option<PathBuf> {
552:     let mut rest: Vec<std::ffi::OsString> = Vec::new();
553:     let mut cur = p.to_path_buf();
554:     loop {
555:         if let Ok(c) = std::fs::canonicalize(&cur) {
556:             let mut out = crate::providers::dunce_simplify(c);
557:             for part in rest.iter().rev() {
558:                 out.push(part);
559:             }
560:             return Some(out);
561:         }
562:         rest.push(cur.file_name()?.to_os_string());
563:         cur = cur.parent()?.to_path_buf();
564:     }
565: }

